} from "@/components/ui/command-palette";
import type { FeatureFlagKey, FeatureFlagSnapshot } from "@/types/feature-flag";
import type { Actor } from "@/types/member";
import type { Organization } from "@/types/organization";
import type { PermissionAction, PermissionResource } from "@/types/permission";
import { orgFlagContext } from "./flag-context";

/** A palette entry plus the gates it depends on. */
export interface CommandSpec extends CommandItemSpec {
  readonly heading: string;
  readonly action?: PermissionAction;
  readonly flag?: FeatureFlagKey;
  /** Which resource the permission is asked about; defaults to the org. */
  readonly scope?: "organization" | "billing" | "activity";
}

export const COMMAND_SPECS: readonly CommandSpec[] = [
  { heading: "Create", id: "create:issue", label: "New issue", shortcut: "c", action: "issue:create" },
  { heading: "Create", id: "create:project", label: "New project", action: "project:create" },
  { heading: "Create", id: "create:invite", label: "Invite teammate", action: "member:invite" },
  { heading: "Go to", id: "nav:issues", label: "Issues", shortcut: "g i", action: "issue:read" },
  { heading: "Go to", id: "nav:projects", label: "Projects", shortcut: "g p", action: "project:read" },
  { heading: "Go to", id: "nav:board", label: "Board", shortcut: "g b", action: "issue:read", flag: "kanban_board" },
  { heading: "Go to", id: "nav:members", label: "Members", action: "member:read" },
  {
    heading: "Go to",
    id: "nav:activity",
    label: "Activity",
    action: "activity:read",
    flag: "activity_feed",
    scope: "activity",
  },
  {
    heading: "Go to",
    id: "nav:billing",
    label: "Billing",
    action: "org:manage_billing",
    scope: "billing",
  },
  {
    heading: "Export",
    id: "export:issues",
    label: "Export issues as CSV",
    hint: "Downloads the current filter",
    action: "issue:read",
    flag: "csv_export",
  },
  {
    heading: "Export",
    id: "export:activity",
    label: "Export audit log as CSV",
    action: "activity:export",
    flag: "csv_export",
    scope: "activity",
  },
];

function resourceFor(spec: CommandSpec, actor: Actor): PermissionResource {
  switch (spec.scope) {
    case "billing":
      return billingResource(actor.orgId);
    case "activity":
      return activityResource(actor.orgId);
    default:
      // Creation and navigation are not scoped to an existing row, so the
      // organization is the resource the role matrix is asked about.
      return organizationResource(actor.orgId);
  }
}

export function buildCommandGroups(
  org: Organization,
  actor: Actor,
  flags: FeatureFlagSnapshot,
): readonly CommandGroup[] {
  const context = orgFlagContext(org, actor);
  // The snapshot was evaluated when the layout rendered; a flag flipped since
  // then is still honoured by re-evaluating against the live context.
  const flagOn = (flag: FeatureFlagKey): boolean =>
    flags[flag] === true || isEnabled(flag, context);

  const groups = new Map<string, CommandItemSpec[]>();

  for (const spec of COMMAND_SPECS) {
    if (spec.flag !== undefined && !flagOn(spec.flag)) continue;
    if (
      spec.action !== undefined &&
      !can(actor, spec.action, resourceFor(spec, actor))
    ) {
      continue;
    }
    const items = groups.get(spec.heading) ?? [];
    items.push({
      id: spec.id,
      label: spec.label,
      ...(spec.hint !== undefined ? { hint: spec.hint } : {}),
      ...(spec.shortcut !== undefined ? { shortcut: spec.shortcut } : {}),
    });
    groups.set(spec.heading, items);
  }

  return [...groups.entries()].map(([heading, items]) => ({ heading, items }));
}
/**
 * Permanently removes rows archived longer ago than the plan's `retentionDays`.
 *
 * Must call (do not reimplement): getPlanLimits, isArchived
 */
import { getPlanLimits } from "@/config/plan-limits";
import { createLogger } from "@/lib/logger";
import { isArchived } from "@/lib/soft-delete";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";

const ORG_BATCH = 25;
const PAGE_SIZE = 100;
const MS_PER_DAY = 24 * 60 * 60 * 1000;

const logger = createLogger("cleanup-archived-job");

/**
 * The retention sweep. Soft-deleted rows are kept for as long as the plan
 * promises and no longer: the cut-off comes from `retentionDays`, so an
 * enterprise tenant keeps years of history where a free one keeps a month.
 *
 * Only the search documents are actually dropped here — the issue rows stay,
 * because the audit log still points at them — while the audit rows past the
 * window are purged outright.
 */
export async function runCleanupArchivedJob(now: Date): Promise<JobResult> {
  return runJob("cleanup-archived", async (result) => {
    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);

    for (const orgId of orgIds) {
      const org = await orgRepo.findOrgById(orgId);
      if (!org) continue;

      const { retentionDays } = getPlanLimits(org.plan);
      const cutoff = toIsoTimestamp(
        new Date(now.getTime() - retentionDays * MS_PER_DAY),
      );

      const archived = await issueRepo.listIssues({
        orgId,
        limit: PAGE_SIZE,
        cursor: null,
        includeArchived: true,
      });

      for (const issue of archived.items) {
        if (!isArchived(issue)) continue;
        if (issue.archivedAt === null || issue.archivedAt > cutoff) continue;

        await searchRepo.deleteSearchDocument(orgId, "issue", issue.id);
        result.processed += 1;
      }

      try {
        const purged = await activityRepo.purgeActivityBefore(orgId, cutoff);
        result.processed += purged;
      } catch (error) {
        result.failed += 1;
        logger.error("activity purge failed", {
          orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}
import {
  FEATURE_FLAG_DEFINITIONS,
  FEATURE_FLAG_KEYS,
} from "@/config/feature-flags";
import { planAtLeast } from "@/config/plan-limits";
import { ROLE_RANK } from "@/types/member";
import type {
  FeatureFlagKey,
  FeatureFlagSnapshot,
  FlagContext,
} from "@/types/feature-flag";

/**
 * Feature-flag evaluation, shared verbatim by server and client.
 *
 * Server code builds a `FlagContext` from the session and calls `isEnabled()`
 * directly; the dashboard layout serialises `snapshotFlags()` into the client
 * provider so `useFeatureFlag()` answers the same way without a round trip.
 * Both sides must agree — never re-implement a strategy at a call site.
 */
export function isEnabled(flag: FeatureFlagKey, ctx: FlagContext): boolean {
  const definition = FEATURE_FLAG_DEFINITIONS[flag];
  if (!definition) return false;

  if (definition.overridable && ctx.overrides?.includes(flag)) {
    return true;
  }

  const strategy = definition.strategy;
  switch (strategy.kind) {
    case "off":
      return false;
    case "on":
      return true;
    case "plan":
      return planAtLeast(ctx.plan, strategy.minPlan);
    case "role":
      return ctx.role !== null && ROLE_RANK[ctx.role] >= ROLE_RANK[strategy.minRole];
    case "percentage":
      return bucketOf(flag, ctx) < strategy.percent;
    default:
      return false;
  }
}

/** Evaluates every flag at once, for handoff to the client provider. */
export function snapshotFlags(ctx: FlagContext): FeatureFlagSnapshot {
  const snapshot = {} as Record<FeatureFlagKey, boolean>;
  for (const key of FEATURE_FLAG_KEYS) {
    snapshot[key] = isEnabled(key, ctx);
  }
  return snapshot;
}

/** Throwing guard for server actions gated behind a flag. */
export class FeatureDisabledError extends Error {
  readonly code = "forbidden" as const;

  constructor(readonly flag: FeatureFlagKey) {
    super(`Feature "${flag}" is not enabled for this organization.`);
    this.name = "FeatureDisabledError";
  }
}

export function assertEnabled(flag: FeatureFlagKey, ctx: FlagContext): void {
  if (!isEnabled(flag, ctx)) {
    throw new FeatureDisabledError(flag);
  }
}

/**
 * Deterministic 0–99 bucket for percentage rollouts. Stable per
 * (flag, org, user) so a viewer never sees the feature flicker.
 */
function bucketOf(flag: FeatureFlagKey, ctx: FlagContext): number {
  const seed = `${flag}:${ctx.orgId ?? "-"}:${ctx.userId ?? "-"}`;
  let hash = 2_166_136_261;
  for (let i = 0; i < seed.length; i += 1) {
    hash ^= seed.charCodeAt(i);
    hash = Math.imul(hash, 16_777_619);
  }
  return Math.abs(hash) % 100;
}
