p='tests/services/search-service.test.ts'
s=open(p).read()

s=s.replace('''import * as commentService from "@/server/services/comment-service";''','''import { emit } from "@/lib/event-bus";
import { runSearchReindexJob } from "@/server/jobs/search-reindex-job";
import * as commentService from "@/server/services/comment-service";''')
s=s.replace('''import type { Tenant } from "../server/_support/fixtures";''','''import type { Tenant } from "../server/_support/fixtures";
import type { CommentId, IssueId } from "@/types/common";''')

s=s.rstrip()
assert s.endswith("});")
s += '''

describe("services/search-service — ADR 0007", () => {
  const ask = (
    t: Tenant,
    q: string,
    extra: { kinds?: ("issue" | "comment" | "project")[]; projectId?: Tenant["project"]["id"] } = {},
  ) =>
    searchService.search(t.actors.member, {
      orgId: t.org.id,
      q,
      kinds: extra.kinds ?? ["issue"],
      ...(extra.projectId !== undefined ? { projectId: extra.projectId } : {}),
      limit: 25,
      cursor: null,
    });

  async function postComment(t: Tenant, issueId: IssueId, body: string) {
    return commentService.createComment(t.actors.member, {
      orgId: t.org.id,
      issueId,
      body,
      parentId: null,
      mentionedUserIds: [],
    });
  }

  it("treats a colon as an ordinary character on a plan without advanced_search", async () => {
    const starter = await createTenant("searchadrstarter", "starter");
    const issue = await issueService.createIssue(
      starter.actors.member,
      issueInput(starter.org.id, starter.project.id, { title: "Release 2: hotfix" }),
    );

    const hits = await ask(starter, "Release 2: hotfix");
    expect(hits.total).toBe(1);
    expect(hits.items[0]).toMatchObject({ id: issue.id });
  });

  it("honours kind:, in: and project: tokens with advanced_search", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Tokens host issue" }),
    );
    const comment = await postComment(tenant, issue.id, "flaky tokenprobe in CI");
    await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "flaky tokenprobe issue" }),
    );

    for (const q of ["kind:comment tokenprobe", "in:comments tokenprobe"]) {
      const hits = await ask(tenant, q);
      expect(hits.total).toBe(1);
      expect(hits.items[0]).toMatchObject({ kind: "comment", id: comment.id });
    }

    const scoped = await ask(tenant, `project:${tenant.project.id} tokenprobe`, {
      kinds: ["issue", "comment"],
    });
    expect(scoped.items.map((hit) => hit.kind).sort()).toEqual(["comment", "issue"]);

    const elsewhere = await ask(tenant, "project:prj_elsewhere tokenprobe", {
      kinds: ["issue", "comment"],
    });
    expect(elsewhere.total).toBe(0);

    // Unknown and empty tokens are dropped, not searched.
    expect((await ask(tenant, "label:x kind: tokenprobe")).total).toBe(1);
  });

  it("finds comments when scoped to their issue's project", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Scope host issue" }),
    );
    const comment = await postComment(tenant, issue.id, "scopeprobe on creation");

    const hits = await ask(tenant, "scopeprobe", {
      kinds: ["comment"],
      projectId: tenant.project.id,
    });
    expect(hits.items.map((hit) => hit.id)).toEqual([comment.id]);

    await commentService.updateComment(tenant.actors.member, {
      orgId: tenant.org.id,
      commentId: comment.id,
      body: "scopeprobe after edit",
    });
    const edited = await ask(tenant, "after edit", {
      kinds: ["comment"],
      projectId: tenant.project.id,
    });
    expect(edited.items.map((hit) => hit.id)).toEqual([comment.id]);
  });

  it("rebuilds comment documents with their project", async () => {
    const rebuilt = await createTenant("searchadrjob", "enterprise");
    const issue = await issueService.createIssue(
      rebuilt.actors.member,
      issueInput(rebuilt.org.id, rebuilt.project.id, { title: "Rebuild host" }),
    );
    const comment = await postComment(rebuilt, issue.id, "rebuildprobe comment");

    await runSearchReindexJob(rebuilt.org.id);

    const hits = await ask(rebuilt, "rebuildprobe", {
      kinds: ["comment"],
      projectId: rebuilt.project.id,
    });
    expect(hits.items.map((hit) => hit.id)).toEqual([comment.id]);
  });

  it("matches % _ and \\\\ literally", async () => {
    const lit = await createTenant("searchadrliteral", "growth");
    for (const title of ["Sales are up 100% today", "snake_case naming", "snake case naming", "path a\\\\b"]) {
      await issueService.createIssue(
        lit.actors.member,
        issueInput(lit.org.id, lit.project.id, { title }),
      );
    }

    expect((await ask(lit, "100%")).total).toBe(1);
    expect((await ask(lit, "snake_case")).total).toBe(1);
    expect((await ask(lit, "a\\\\b")).total).toBe(1);
    expect((await ask(lit, "%")).total).toBe(1);
  });

  it("searches issues only without advanced_search, whatever kinds were asked for", async () => {
    const growth = await createTenant("searchadrgrowth", "growth");
    const issue = await issueService.createIssue(
      growth.actors.member,
      issueInput(growth.org.id, growth.project.id, { title: "gatedprobe issue" }),
    );
    await postComment(growth, issue.id, "gatedprobe comment");

    const hits = await ask(growth, "gatedprobe", { kinds: ["issue", "comment", "project"] });
    expect(hits.total).toBe(1);
    expect(hits.items.map((hit) => hit.kind)).toEqual(["issue"]);

    const viaToken = await ask(growth, "kind:comment gatedprobe", { kinds: ["comment"] });
    expect(viaToken.total).toBe(0);
  });

  it("re-indexes any kind on request and leaves archived or missing subjects out", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { title: "Reindex host" }),
    );
    const comment = await postComment(tenant, issue.id, "reindexprobe comment");
    const request = (subjectKind: "issue" | "comment" | "project", subjectId: string) =>
      emit("search.reindex_requested", {
        orgId: tenant.org.id,
        actorId: null,
        occurredAt: new Date().toISOString() as never,
        subjectKind,
        subjectId,
      });

    await searchService.removeFromIndex(tenant.org.id, "comment", comment.id);
    await searchService.removeFromIndex(tenant.org.id, "project", tenant.project.id);
    expect((await ask(tenant, "reindexprobe", { kinds: ["comment"] })).total).toBe(0);

    await request("comment", comment.id);
    await request("project", tenant.project.id);

    const commentHits = await ask(tenant, "reindexprobe", {
      kinds: ["comment"],
      projectId: tenant.project.id,
    });
    expect(commentHits.items.map((hit) => hit.id)).toEqual([comment.id]);
    const projectHits = await ask(tenant, "platform", { kinds: ["project"] });
    expect(projectHits.items.map((hit) => hit.id)).toContain(tenant.project.id);

    await issueService.archiveIssue(tenant.actors.member, tenant.org.id, issue.id);
    await request("issue", issue.id);
    expect((await ask(tenant, "Reindex host")).total).toBe(0);

    await request("comment", "cmt_missing" as CommentId);
  });
});
'''
open(p,'w').write(s+"\n")
EOF
